import { resolve } from "node:path";
import { defineConfig } from "vite";
import { TOOLS } from "./site/catalog.mjs";

// GitHub Pages serves this project from /<repo>/. The deploy workflow sets
// BASE_PATH; local development keeps the site at the server root.
// Every tool is its own HTML page (generated by scripts/build-pages.mjs).
export default defineConfig({
  base: process.env.BASE_PATH ?? "/",
  server: { host: "127.0.0.1", port: 5184, strictPort: true },
  preview: { host: "127.0.0.1", port: 5184, strictPort: true },
  build: {
    target: "es2022",
    rollupOptions: {
      input: Object.fromEntries(
        TOOLS.map((tool) => [tool.id, resolve(import.meta.dirname, tool.slug, "index.html")]),
      ),
    },
  },
});
